import java.nio.charset.StandardCharsets;
import java.util.Base64;

@SpringBootApplication
public class ImageServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(ImageServiceApplication.class, args);
    }
}

@RestController
@RequestMapping("/api/v1/images")
class ImageProcessingController {

    // Native library for high-performance image resizing
    static {
        System.loadLibrary("imageproc_native");
    }

    // JNI method - implemented in C, vulnerable to buffer overflow
    private native byte[] nativeResize(byte[] imageData, int width, int height, byte[] metadataTag);
    private native byte[] nativeExtractExif(byte[] imageData, byte[] fieldSelector);

    @PostMapping("/resize")
    public ResponseEntity<byte[]> resizeImage(
            @RequestParam("width") int width,
            @RequestParam("height") int height,
            @RequestParam(value = "tag", defaultValue = "default") String metadataTag,
            @RequestBody byte[] imageData) {

        if (imageData == null || imageData.length == 0) {
            return ResponseEntity.badRequest().build();
        }

        // Tag is passed directly to native code without length validation
        // The native C code uses a fixed 64-byte stack buffer for the tag
        byte[] tagBytes = metadataTag.getBytes(StandardCharsets.UTF_8);

        try {
            byte[] result = nativeResize(imageData, width, height, tagBytes);
            return ResponseEntity.ok(result);
        } catch (Exception e) {
            return ResponseEntity.internalServerError().build();
        }
    }

    @PostMapping("/exif")
    public ResponseEntity<byte[]> extractExif(
            @RequestParam("field") String fieldSelector,
            @RequestBody byte[] imageData) {

        if (imageData == null || imageData.length == 0) {
            return ResponseEntity.badRequest().build();
        }

        // fieldSelector also passed without bounds checking to native layer
        byte[] selectorBytes = fieldSelector.getBytes(StandardCharsets.UTF_8);

        try {
            byte[] result = nativeExtractExif(imageData, selectorBytes);
            return ResponseEntity.ok(result);
        } catch (Exception e) {
            return ResponseEntity.internalServerError().build();
        }
    }
}

